CARDIO.register({"item":"d171","meta":{"num":"d171","label":"171","spe":"dermato","short":"Gale et pédiculose","title":"Ectoparasitoses cutanées : gale et pédiculose","section":"D","chapter":12,"pages":"248-259","sdd":[{"num":88,"label":"Prurit"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":263,"label":"Prise en charge d'une ectoparasitose"},{"num":310,"label":"Prévention chez un malade contagieux"}]},"objectives":[{"id":"d171-obj-01","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître les modes de transmission principaux et l'épidémiologie de la gale et des pédiculoses","desc":""},{"id":"d171-obj-02","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître la physiopathologie de la gale","desc":""},{"id":"d171-obj-03","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître les différents agents des pédiculoses","desc":""},{"id":"d171-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes évocateurs de gale et de pédiculoses","desc":"Gale, pédiculoses de la tête, du corps et du pubis"},{"id":"d171-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes atypiques de gale et de pédiculoses","desc":""},{"id":"d171-obj-06","rank":"A","rubric":"Contenu multimédia","title":"Lésions de gale","desc":""},{"id":"d171-obj-07","rank":"A","rubric":"Contenu multimédia","title":"Photographie d'une pédiculose du cuir chevelu","desc":"Cheveux avec lentes, image de poux"},{"id":"d171-obj-08","rank":"A","rubric":"Examens complémentaires","title":"Savoir associer un bilan d'IST au diagnostic de gale ou pédiculose de corps ou de pubis","desc":""},{"id":"d171-obj-09","rank":"B","rubric":"Examens complémentaires","title":"Connaître les indications du diagnostic parasitologique","desc":""},{"id":"d171-obj-10","rank":"B","rubric":"Diagnostic positif","title":"Connaître l'intérêt du dermatoscope pour le diagnostic de gale","desc":"Identification d'un sillon et observation du sarcopte"},{"id":"d171-obj-11","rank":"A","rubric":"Prise en charge","title":"Connaître le traitement d'une gale et d'une pédiculose","desc":""},{"id":"d171-obj-12","rank":"A","rubric":"Prise en charge","title":"Savoir traiter les sujets contacts en cas de diagnostic de gale","desc":"Traitement selon les recommandations nationales"},{"id":"d171-obj-13","rank":"B","rubric":"Prise en charge","title":"Connaître les causes d'échec du traitement de la gale et des pédiculoses","desc":""},{"id":"d171-obj-14","rank":"B","rubric":"Prise en charge","title":"Savoir gérer une épidémie de gale dans un établissement","desc":"Voir recommandations nationales"}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d171-qroc-001","type":"QROC","rank":"A","objective":"d171-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quel est l'agent responsable de la gale humaine ?","answer":"Sarcoptes scabiei variété hominis","accept":["Sarcoptes scabiei","Sarcoptes scabiei hominis","S. scabiei"],"keywords":["sarcopt"],"explanation":"La gale est due à la contamination de la peau par un acarien, Sarcoptes scabiei variété hominis. Les signes cliniques résultent à la fois de l'infestation parasitaire et de la réaction de l'organisme contre les sarcoptes et leurs déjections.","src":"p. 249"},{"id":"d171-qroc-002","type":"QROC","rank":"B","objective":"d171-obj-01","tags":["épidémiologie"],"difficulty":2,"question":"Quel est le mode de transmission principal de la gale humaine ?","answer":"Contact interhumain direct, intime et prolongé","accept":["contacts intimes et prolongés","interhumaine directe","contact direct"],"keywords":["direct","intime"],"explanation":"La transmission est interhumaine directe, par des contacts intimes et prolongés (famille, couple), ce qui impose de rechercher des rapports sexuels à risque. La transmission indirecte par vêtements ou literie est beaucoup plus rare, sauf dans les formes profuses et hyperkératosiques.","src":"p. 249"},{"id":"d171-qroc-003","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":1,"question":"Quel est le rythme du prurit de la gale et quelle région du corps épargne-t-il ?","answer":"Recrudescence nocturne ; épargne le visage","accept":["prurit nocturne épargnant le visage","nocturne et épargne le visage","nocturne, visage épargné"],"keywords":["nocturne","visage"],"explanation":"Le prurit de la gale est diffus, à recrudescence nocturne, et épargne le visage ; il a souvent un caractère conjugal ou familial.","src":"p. 250"},{"id":"d171-qroc-004","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel caractère du prurit, dans l'entourage du patient, oriente vers une gale ?","answer":"Un prurit conjugal ou familial","accept":["conjugal","familial","plusieurs membres de la famille"],"keywords":["famili"],"explanation":"Un prurit conjugal ou familial doit faire penser à la gale. Il faut y penser devant tout prurit, car certaines formes sont pauci-lésionnelles.","src":"p. 250"},{"id":"d171-qroc-005","type":"QROC","rank":"A","objective":"d171-obj-06","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on la lésion sinueuse de quelques millimètres qui correspond au trajet de l'acarien femelle dans la couche cornée ?","answer":"Le sillon scabieux","accept":["sillon","sillons scabieux"],"keywords":["sillon"],"explanation":"Chaque sillon scabieux contient les œufs pondus et peut présenter, à une extrémité, une discrète surélévation correspondant à la position de l'acarien femelle (éminence acarienne).","src":"p. 250"},{"id":"d171-qroc-006","type":"QROC","rank":"A","objective":"d171-obj-06","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on les petites élevures translucides sur base érythémateuse, situées surtout dans les espaces interdigitaux, au cours de la gale ?","answer":"Les vésicules perlées","accept":["vésicule perlée","vésicules perlées"],"keywords":["perlé"],"explanation":"Les vésicules perlées sont des lésions spécifiques de la gale, à rechercher systématiquement avec les sillons et les nodules scabieux.","src":"p. 250"},{"id":"d171-qroc-007","type":"QROC","rank":"A","objective":"d171-obj-06","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on les papulo-nodules rouges ou violacés, prurigineux, parfois excoriés, siégeant surtout sur les organes génitaux de l'homme ?","answer":"Les nodules scabieux","accept":["nodule scabieux","nodules scabieux"],"keywords":["scabieux"],"explanation":"Les nodules scabieux sont une lésion spécifique de la gale ; il ne faut pas les confondre avec les nodules post-scabieux, qui persistent après un traitement efficace et ne contiennent pas de sarcopte.","src":"p. 250"},{"id":"d171-qroc-008","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":1,"question":"Où siègent les sillons scabieux ?","answer":"Entre les doigts et sur la face antérieure des poignets","accept":["espaces interdigitaux et poignets","interdigitaux et face antérieure des poignets","espaces interdigitaux et face antérieure des poignets"],"keywords":["doigts","poignet"],"explanation":"Les sillons siègent entre les doigts et sur la face antérieure des poignets ; les vésicules perlées touchent surtout les espaces interdigitaux.","src":"p. 250"},{"id":"d171-qroc-009","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":2,"question":"Quelles localisations des lésions de grattage sont propres à l'homme et à la femme dans la gale ?","answer":"Organes génitaux externes (homme) ; mamelon et aréole (femme)","accept":["OGE et mamelon","organes génitaux externes et mamelon","verge et mamelon"],"keywords":["génit","mamelon"],"explanation":"Les autres topographies évocatrices sont les espaces interdigitaux, la face antérieure des poignets, les coudes et emmanchures antérieures, l'ombilic, les fesses et la face interne des cuisses.","src":"p. 250"},{"id":"d171-qroc-010","type":"QROC","rank":"A","objective":"d171-obj-08","tags":["biologie","prévention"],"difficulty":1,"question":"Quel bilan faut-il prescrire devant une gale chez un patient ayant eu des rapports sexuels à risque ?","answer":"Un bilan d'IST","accept":["bilan d'IST","bilan IST","dépistage des IST","IST","infections sexuellement transmissibles"],"keywords":["IST"],"explanation":"Il n'existe pas de signe biologique spécifique de la gale ; en cas de rapports sexuels à risque, on prescrit un bilan d'IST.","src":"p. 252"},{"id":"d171-qroc-011","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["diagnostic"],"difficulty":1,"question":"Sur quoi repose avant tout le diagnostic de gale ?","answer":"La clinique : anamnèse et topographie évocatrice","accept":["clinique","diagnostic clinique","interrogatoire et examen clinique"],"keywords":["clinique"],"explanation":"Le diagnostic repose sur l'anamnèse (prurit nocturne, familial ou du partenaire sexuel) et sur une éruption de topographie évocatrice. L'examen parasitologique peut le confirmer mais n'est pas obligatoire.","src":"p. 252"},{"id":"d171-qroc-012","type":"QROC","rank":"B","objective":"d171-obj-10","tags":["paraclinique"],"difficulty":2,"question":"Comment nomme-t-on l'aspect caractéristique de la gale en dermatoscopie ?","answer":"Le signe du deltaplane","accept":["deltaplane","en deltaplane"],"keywords":["deltaplane"],"explanation":"La dermatoscopie, qui montre un aspect « en deltaplane », peut remplacer l'examen parasitologique, peu accessible en médecine de ville et jamais obligatoire pour le diagnostic.","src":"p. 252-253"},{"id":"d171-qroc-013","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement de la gale par voie orale ?","answer":"L'ivermectine","accept":["ivermectine"],"keywords":["ivermectine"],"explanation":"L'ivermectine se donne par voie orale en prise unique, à répéter 7 à 14 jours plus tard.","src":"p. 253"},{"id":"d171-qroc-014","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"question":"Quelle dose d'ivermectine administre-t-on par voie orale dans la gale ?","answer":"200 µg/kg en prise unique","accept":["200 µg/kg","200 ug/kg","200 mcg/kg","200 microgrammes par kg"],"keywords":["200"],"explanation":"L'ivermectine (200 µg/kg par voie orale, en une prise) a l'AMM chez l'adulte et chez l'enfant de plus de 2 ans et de plus de 15 kg.","src":"p. 253"},{"id":"d171-qroc-015","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","pièges"],"difficulty":2,"question":"À quel délai la prise d'ivermectine doit-elle être répétée dans la gale ?","answer":"7 à 14 jours plus tard","accept":["7 à 14 jours","7-14 jours","J7-J14","entre 7 et 14 jours"],"keywords":["7","14"],"explanation":"La seconde dose, hors AMM, est indispensable pour éviter les échecs de traitement, en raison du cycle du parasite.","src":"p. 253"},{"id":"d171-qroc-016","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"question":"Pourquoi l'application du traitement local de la gale est-elle répétée 8 jours plus tard ?","answer":"Mauvaise action sur les œufs","accept":["action insuffisante sur les œufs","les œufs","il agit mal sur les œufs"],"keywords":["œufs"],"explanation":"Le produit agit mal sur les œufs. L'alternative locale est la perméthrine à 5 % en crème, appliquée 8 à 12 heures et renouvelée 7 jours plus tard.","src":"p. 253-254"},{"id":"d171-qroc-017","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":1,"question":"Pendant combien de temps l'adulte ne doit-il pas se laver après l'application d'un traitement local antiscabieux ?","answer":"24 heures","accept":["24 h","24h","24 heures"],"keywords":["24"],"explanation":"On applique le produit après une douche tiède au savon, sur tout le corps, puis on attend 24 heures avant de se laver à l'eau et au savon ; la peau, alors sèche et prurigineuse, justifie un soin émollient.","src":"p. 253"},{"id":"d171-qroc-018","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"question":"Quelle est l'alternative locale, en crème à 5 %, pour traiter la gale ?","answer":"La perméthrine","accept":["perméthrine","perméthrine à 5 %"],"keywords":["perméthrine"],"explanation":"La perméthrine à 5 % en crème est appliquée 8 à 12 heures puis renouvelée 7 jours plus tard.","src":"p. 254"},{"id":"d171-qroc-019","type":"QROC","rank":"A","objective":"d171-obj-12","tags":["prévention"],"difficulty":1,"question":"Qui faut-il traiter simultanément en cas de gale ?","answer":"Le malade et ses contacts intimes (famille, partenaires)","accept":["le malade et les sujets contacts","malade et contacts","sujets contacts","les contacts"],"keywords":["contact"],"explanation":"Le traitement simultané concerne la personne parasitée et toute personne ayant eu un contact intime avec elle (famille, partenaires sexuels), sans oublier le linge et la literie.","src":"p. 254, 258"},{"id":"d171-qroc-020","type":"QROC","rank":"A","objective":"d171-obj-12","tags":["prévention"],"difficulty":2,"question":"À quelle température minimale lave-t-on le linge, les draps et les serviettes d'un patient atteint de gale ?","answer":"Au-delà de 60 °C","accept":["60 °C","60°C","plus de 60 °C","60 degrés"],"keywords":["60"],"explanation":"Le lavage se fait si possible à haute température, au-delà de 60 °C, avec sèche-linge et repassage si possible. Il n'y a pas de désinfection de l'environnement en cas de gale commune.","src":"p. 254"},{"id":"d171-qroc-021","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"question":"En cas de gale profuse ou hyperkératosique, quelles voies de traitement sont associées ?","answer":"Traitement oral + traitement local","accept":["oral et local","PO et local","ivermectine et local","général et local","voie générale et locale"],"keywords":["local"],"explanation":"Il faut aussi isoler le malade (idéalement hospitalisé), définir largement les sujets contacts et prescrire une antibiothérapie en cas d'impétiginisation.","src":"p. 254"},{"id":"d171-qroc-022","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","prévention"],"difficulty":2,"question":"Dans quel type de gale envisage-t-on une décontamination des lieux de vie ?","answer":"La gale profuse","accept":["gale profuse","formes profuses","profuse"],"keywords":["profus"],"explanation":"En cas de gale commune, il n'y a pas de désinfection de l'environnement ; une décontamination des lieux de vie est à envisager dans la gale profuse.","src":"p. 254"},{"id":"d171-qroc-023","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","pièges"],"difficulty":2,"question":"Que faire devant des nodules post-scabieux qui persistent après un traitement efficace ?","answer":"Ne pas retraiter","accept":["pas de retraitement","aucun retraitement","pas d'indication de retraitement"],"keywords":[],"explanation":"Les nodules post-scabieux, d'origine immuno-allergique, ne contiennent pas de sarcopte et peuvent persister plusieurs semaines : ils ne constituent pas une indication de retraitement.","src":"p. 252, 254"},{"id":"d171-qroc-024","type":"QROC","rank":"B","objective":"d171-obj-14","tags":["prévention","pédiatrie"],"difficulty":2,"question":"Jusqu'à quand un enfant atteint de gale commune est-il évincé de la collectivité ?","answer":"3 jours après le traitement","accept":["3 jours après le traitement","jusqu'à 3 jours après le traitement","3 jours"],"keywords":["3"],"explanation":"Pour les gales profuses et hyperkératosiques, l'éviction dure jusqu'à négativation de l'examen parasitologique.","src":"p. 254"},{"id":"d171-qroc-025","type":"QROC","rank":"B","objective":"d171-obj-13","tags":["pièges"],"difficulty":2,"question":"Parmi les causes d'un prurit qui persiste 8 à 15 jours après le traitement d'une gale, laquelle est de nature psychologique ?","answer":"Une parasitophobie","accept":["parasitophobie"],"keywords":["parasitophobie"],"explanation":"Les autres causes sont l'irritation par le traitement, l'eczéma de contact, d'autres causes de prurit et un échec du traitement (lésions évocatrices et/ou examen parasitologique positif).","src":"p. 255"},{"id":"d171-qroc-026","type":"QROC","rank":"B","objective":"d171-obj-05","tags":["clinique"],"difficulty":2,"question":"Quelle forme de gale touche les immunodéprimés ou les sujets âgés sous immunosuppresseurs, avec contagiosité majeure et prurit souvent discret ?","answer":"La gale hyperkératosique","accept":["hyperkératosique","gale hyperkératosique"],"keywords":["hyperkérat"],"explanation":"Elle atteint tout le corps, y compris le visage, le cuir chevelu et les ongles, voire une érythrodermie avec zones hyperkératosiques ; l'acarien y est facile à mettre en évidence.","src":"p. 252"},{"id":"d171-qroc-027","type":"QROC","rank":"B","objective":"d171-obj-05","tags":["clinique","pédiatrie"],"difficulty":2,"question":"Quelle atteinte des paumes et des plantes est particulière à la gale du nourrisson ?","answer":"Des vésiculo-pustules palmaires et plantaires","accept":["vésiculo-pustules","vésiculopustules palmo-plantaires","vésiculo-pustules palmo-plantaires"],"keywords":["vésiculo","palm"],"explanation":"Chez le nourrisson, on observe aussi des nodules scabieux péri-axillaires et une atteinte possible du visage : des vésicules palmaires ou plantaires, ou un visage atteint, doivent faire évoquer une gale.","src":"p. 251, 258"},{"id":"d171-qroc-028","type":"QROC","rank":"B","objective":"d171-obj-05","tags":["complications"],"difficulty":2,"question":"Un impétigo chez l'adulte doit faire rechercher quelle ectoparasitose ?","answer":"Une gale","accept":["gale","la gale"],"keywords":["gale"],"explanation":"L'impétiginisation est une complication de la gale ; dans les pays en développement, la gale surinfectée est une cause majeure de rhumatisme articulaire aigu et de glomérulonéphrite post-streptococcique.","src":"p. 252, 258"},{"id":"d171-qroc-029","type":"QROC","rank":"A","objective":"d171-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quel est l'agent de la pédiculose du cuir chevelu ?","answer":"Pediculus humanus var. capitis (pou de tête)","accept":["Pediculus humanus capitis","pou de tête","P. humanus capitis"],"keywords":["capitis"],"explanation":"Le pou de tête infeste le cuir chevelu et touche avec prédilection les enfants d'âge scolaire et les sujets en situation de précarité.","src":"p. 255"},{"id":"d171-qroc-030","type":"QROC","rank":"A","objective":"d171-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quel est l'agent de la pédiculose corporelle ?","answer":"Pediculus humanus var. corporis (pou de corps)","accept":["Pediculus humanus corporis","pou de corps","P. humanus corporis"],"keywords":["corporis"],"explanation":"La pédiculose corporelle touche avec prédilection les sujets en état de précarité.","src":"p. 256"},{"id":"d171-qroc-031","type":"QROC","rank":"A","objective":"d171-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quel est l'agent de la phtiriase (poux de pubis, morpion) ?","answer":"Phtirius inguinalis","accept":["Phtirius inguinalis"],"keywords":["phtirius"],"explanation":"La phtiriase est une ectoparasitose due à Phtirius inguinalis ; c'est une infection sexuellement transmissible.","src":"p. 256-257"},{"id":"d171-qroc-032","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quelle population est touchée avec prédilection par la pédiculose du cuir chevelu ?","answer":"Les enfants d'âge scolaire","accept":["enfants d'âge scolaire","enfant d'âge scolaire","enfants scolarisés"],"keywords":["scolaire"],"explanation":"La pédiculose du cuir chevelu touche aussi les sujets en situation de précarité ; la transmission est le plus souvent directe, par contact des têtes en milieu scolaire.","src":"p. 255"},{"id":"d171-qroc-033","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":2,"question":"Quelle est la localisation prédominante du prurit dans la pédiculose du cuir chevelu ?","answer":"Rétro-auriculaire (jusqu'à la nuque)","accept":["rétro-auriculaire","retro auriculaire","derrière les oreilles"],"keywords":["auricul"],"explanation":"Le prurit est diffus ou à prédominance rétro-auriculaire, pouvant s'étendre vers la nuque ; on observe des lésions de grattage, parfois des croûtes surinfectées et des adénopathies cervicales.","src":"p. 255"},{"id":"d171-qroc-034","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle ectoparasitose faut-il rechercher devant un impétigo de la nuque ou du cuir chevelu ?","answer":"Une pédiculose","accept":["pédiculose","pédiculose du cuir chevelu","poux"],"keywords":["pédicul"],"explanation":"Tout impétigo de la nuque ou du cuir chevelu doit faire rechercher une pédiculose.","src":"p. 255"},{"id":"d171-qroc-035","type":"QROC","rank":"A","objective":"d171-obj-07","tags":["diagnostic"],"difficulty":2,"question":"Quelle découverte permet d'affirmer avec certitude une pédiculose du cuir chevelu ?","answer":"Des poux vivants","accept":["poux vivants","pou vivant","la découverte de poux vivants"],"keywords":["poux"],"explanation":"Les poux vivants sont visibles à l'œil nu et très mobiles. La présence de lentes vivantes oriente seulement le diagnostic.","src":"p. 255"},{"id":"d171-qroc-036","type":"QROC","rank":"A","objective":"d171-obj-07","tags":["clinique"],"difficulty":2,"question":"Les lentes sont des œufs de pou collés aux cheveux : comment se comportent-elles le long de la tige pilaire ?","answer":"Elles ne coulissent pas","accept":["ne coulissent pas","ne coulisse pas","ne glissent pas","ne bougent pas"],"keywords":[],"explanation":"Les lentes, visibles à l'œil nu, sont plus faciles à mettre en évidence dans les régions rétro-auriculaires ; elles orientent le diagnostic mais ne le prouvent pas.","src":"p. 255"},{"id":"d171-qroc-037","type":"QROC","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":1,"question":"Dans quelle partie des vêtements retrouve-t-on préférentiellement les poux de corps ?","answer":"Les coutures","accept":["coutures","les coutures"],"keywords":["couture"],"explanation":"Le diagnostic de certitude de la pédiculose corporelle repose sur la découverte de poux sur le corps lors du déshabillage ou dans les vêtements, en particulier les coutures.","src":"p. 256"},{"id":"d171-qroc-038","type":"QROC","rank":"A","objective":"d171-obj-08","tags":["clinique","prévention"],"difficulty":1,"question":"Quelle ectoparasitose est une infection sexuellement transmissible ?","answer":"La phtiriase (poux de pubis)","accept":["phtiriase","poux de pubis","pou de pubis","morpion","morpions"],"keywords":["phtiriase"],"explanation":"Le pou de pubis vit accroché aux poils de la région génitale ; on dépiste une autre IST associée et on traite les partenaires.","src":"p. 257-258"},{"id":"d171-qroc-039","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","pièges"],"difficulty":2,"question":"Pourquoi prescrit-on systématiquement un second traitement 7 à 10 jours après le premier dans les pédiculoses ?","answer":"Mauvais effet lenticide des produits","accept":["effet lenticide insuffisant","mauvais effet lenticide","lentes non détruites"],"keywords":["lenticide"],"explanation":"Le second traitement détruit les poux nés des lentes qui ont survécu au premier produit.","src":"p. 257"},{"id":"d171-qroc-040","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":1,"question":"Quelles formes de produits antipoux sont moins efficaces et ne devraient plus être utilisées ?","answer":"Les shampooings et les poudres","accept":["shampooings et poudres","shampooing et poudre"],"keywords":["shampooing","poudre"],"explanation":"On préfère les solutions, lotions ou crèmes ; les shampooings ne sont jamais curatifs et pourraient favoriser l'émergence de résistances.","src":"p. 257"},{"id":"d171-qroc-041","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","pièges"],"difficulty":3,"question":"Après le traitement d'une pédiculose du cuir chevelu, des poux vivants sont retrouvés au contrôle à J2, ou à J12 : quelle attitude dans chaque cas ?","answer":"J2 : changer de classe ; J12 : reprendre le produit initial","accept":["J2 changer de classe J12 produit initial"],"keywords":["classe","initial"],"explanation":"À J2, une résistance des poux aux insecticides est probable, d'où le changement de classe pharmacologique ; à J12, il s'agit d'un effet lenticide insuffisant, et le produit initial peut être repris.","src":"p. 257"},{"id":"d171-qroc-042","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement","prévention"],"difficulty":2,"question":"À quelle température minimale lave-t-on les vêtements et la literie en cas de pédiculose du cuir chevelu ?","answer":"50 °C","accept":["50 °C","50°C","au moins 50 °C","50 degrés"],"keywords":["50"],"explanation":"On peut aussi utiliser un aérosol insecticide ; la désinfection des locaux est inutile.","src":"p. 257-258"},{"id":"d171-qroc-043","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"question":"Quel est le traitement habituellement suffisant de la pédiculose corporelle ?","answer":"La décontamination du linge et de la literie","accept":["décontamination du linge","lavage du linge et de la literie","traitement du linge"],"keywords":["linge"],"explanation":"Le pou de corps se réfugie dans les vêtements et y pond ses œufs : c'est le linge qu'il faut traiter.","src":"p. 256, 258"},{"id":"d171-qroc-044","type":"QROC","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":1,"question":"Quel est le meilleur traitement des poux de pubis ?","answer":"Le rasage","accept":["rasage"],"keywords":["rasage"],"explanation":"Les poux de pubis relèvent sinon du même traitement que la pédiculose du cuir chevelu ; il faut dépister une autre IST associée et traiter les partenaires.","src":"p. 258"},{"id":"d171-qru-101","type":"QRU","rank":"A","objective":"d171-obj-06","tags":["clinique"],"difficulty":1,"stem":"Parmi les lésions suivantes, laquelle est spécifique de la gale ?","options":[{"t":"Excoriations de la face antérieure des poignets","ok":false,"why":"Ce sont des lésions de grattage, fréquentes mais non spécifiques."},{"t":"Papules excoriées des fesses","ok":false,"why":"Lésions de grattage non spécifiques, même si leur topographie est évocatrice."},{"t":"Sillon scabieux","ok":true,"why":"Le sillon, trajet sinueux de l'acarien femelle dans la couche cornée, est une lésion spécifique à rechercher systématiquement."},{"t":"Lésions eczématiformes de l'ombilic","ok":false,"why":"Les lésions de l'ombilic sont des lésions de grattage non spécifiques."},{"t":"Papules excoriées de la face interne des cuisses","ok":false,"why":"Lésions de grattage non spécifiques de topographie évocatrice."}],"explanation":"Les lésions spécifiques de la gale sont les sillons scabieux, les vésicules perlées et les nodules scabieux ; les lésions de grattage, fréquentes, ne sont pas spécifiques.","src":"p. 250"},{"id":"d171-qru-102","type":"QRU","rank":"A","objective":"d171-obj-11","tags":["traitement","pédiatrie"],"difficulty":2,"stem":"Quelles sont les limites d'âge et de poids de l'AMM de l'ivermectine orale dans la gale ?","options":[{"t":"Dès l'âge de 1 mois, quel que soit le poids","ok":false,"why":"L'AMM concerne l'adulte et l'enfant de plus de 2 ans et de plus de 15 kg."},{"t":"Plus de 2 ans et plus de 15 kg","ok":true,"why":"L'ivermectine a l'AMM chez l'adulte et chez l'enfant de plus de 2 ans et de plus de 15 kg."},{"t":"Plus de 6 ans et plus de 25 kg","ok":false,"why":"Le seuil de l'AMM est plus bas : plus de 2 ans et plus de 15 kg."},{"t":"Uniquement chez l'adulte","ok":false,"why":"L'AMM inclut aussi l'enfant de plus de 2 ans et de plus de 15 kg."},{"t":"Plus de 12 ans et plus de 40 kg","ok":false,"why":"Le seuil de l'AMM est plus bas : plus de 2 ans et plus de 15 kg."}],"explanation":"L'ivermectine (200 µg/kg par voie orale) a l'AMM chez l'adulte et chez l'enfant de plus de 2 ans et de plus de 15 kg ; la seconde prise à 7-14 jours est hors AMM mais indispensable.","src":"p. 253"},{"id":"d171-qru-103","type":"QRU","rank":"A","objective":"d171-obj-07","tags":["diagnostic"],"difficulty":2,"stem":"Un enfant de 8 ans a un prurit rétro-auriculaire avec des lésions de grattage de la nuque. Quel élément permet d'affirmer avec certitude une pédiculose du cuir chevelu ?","options":[{"t":"La présence de lentes collées aux cheveux","ok":false,"why":"Les lentes orientent seulement le diagnostic."},{"t":"La découverte de poux vivants","ok":true,"why":"Seuls les poux vivants, visibles à l'œil nu et très mobiles, fournissent le diagnostic de certitude."},{"t":"Des adénopathies cervicales","ok":false,"why":"Elles peuvent accompagner une pédiculose mais ne la prouvent pas."},{"t":"Des lésions croûteuses surinfectées de la nuque","ok":false,"why":"Elles doivent faire rechercher une pédiculose sans l'affirmer."},{"t":"Un prurit à prédominance rétro-auriculaire","ok":false,"why":"Il est évocateur, pas certain."}],"explanation":"Le diagnostic de certitude de la pédiculose du cuir chevelu repose sur la découverte de poux vivants ; les lentes vivantes orientent seulement.","src":"p. 255"},{"id":"d171-qru-104","type":"QRU","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"stem":"Quelle mesure est recommandée dans la prise en charge d'une pédiculose du cuir chevelu ?","options":[{"t":"Un traitement préventif par shampooing antipoux de tous les camarades de classe","ok":false,"why":"Le traitement préventif, notamment par shampooings, n'a aucun intérêt."},{"t":"Un traitement présomptif devant tout prurit du cuir chevelu","ok":false,"why":"Il n'y a pas de traitement présomptif : on traite les sujets parasités."},{"t":"Un second traitement 7 à 10 jours après le premier","ok":true,"why":"Les produits ont un mauvais effet lenticide : un second traitement est prescrit systématiquement."},{"t":"Une éviction scolaire systématique de l'enfant","ok":false,"why":"L'éviction scolaire n'est pas systématique."},{"t":"Une désinfection des locaux de la classe","ok":false,"why":"La désinfection des locaux est inutile."}],"explanation":"Dans les pédiculoses, on prescrit systématiquement un second traitement 7 à 10 jours plus tard, du fait du mauvais effet lenticide des produits.","src":"p. 257-258"},{"id":"d171-qru-105","type":"QRU","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":2,"stem":"Contrairement aux poux de tête et de corps, très mobiles, comment vit le pou de pubis ?","options":[{"t":"Il circule librement sur toute la peau, comme le pou de tête","ok":false,"why":"C'est le comportement des poux de tête et de corps, très mobiles."},{"t":"Il se réfugie dans les vêtements après s'être nourri et y pond ses œufs","ok":false,"why":"C'est le comportement du pou de corps."},{"t":"Il vit accroché aux poils génitaux, près de leur émergence","ok":true,"why":"Le pou de pubis pond ses œufs sur la pilosité génitale."},{"t":"Il vit dans la literie et le linge de lit, loin de la peau","ok":false,"why":"Ce n'est pas son mode de vie : il reste accroché aux poils."},{"t":"Il vit uniquement dans les cils, sans toucher les poils","ok":false,"why":"La colonisation des cils est possible, mais le pou vit surtout accroché aux poils génitaux, parfois péri-anaux, axillaires ou pectoraux."}],"explanation":"Le pou de pubis (Phtirius inguinalis) vit accroché aux poils de la région génitale ; les poils péri-anaux, axillaires et pectoraux et les cils peuvent aussi être touchés ; la phtiriase est une IST.","src":"p. 257"},{"id":"d171-qru-106","type":"QRU","rank":"A","objective":"d171-obj-12","tags":["prévention"],"difficulty":2,"stem":"Quelle mesure environnementale est recommandée en cas de gale commune ?","options":[{"t":"Laver linge, draps et serviettes, si possible à haute température","ok":true,"why":"Lavage à plus de 60 °C avec sèche-linge et repassage si possible."},{"t":"Désinfecter les locaux de vie avec un produit insecticide, par précaution","ok":false,"why":"Il n'y a pas de désinfection de l'environnement en cas de gale commune."},{"t":"Jeter tous les vêtements et la literie du malade après le traitement","ok":false,"why":"Il suffit de laver le linge ; ce n'est pas une mesure recommandée."},{"t":"Interdire l'accès à la chambre du malade pendant plusieurs semaines","ok":false,"why":"Cette mesure n'est pas recommandée : la décontamination des lieux de vie n'est à envisager que dans la gale profuse."},{"t":"Aucune mesure sur le linge si le malade et ses contacts sont traités","ok":false,"why":"Le linge et la literie doivent être traités en même temps que le malade et ses contacts."}],"explanation":"Dans la gale commune, on lave le linge, les draps et les serviettes (si possible à plus de 60 °C) sans désinfecter l'environnement ; une décontamination des lieux de vie se discute en cas de gale profuse.","src":"p. 254, 258"},{"id":"d171-qru-107","type":"QRU","rank":"A","objective":"d171-obj-08","tags":["clinique","prévention"],"difficulty":1,"stem":"Laquelle de ces affections est une infection sexuellement transmissible ?","options":[{"t":"Pédiculose du cuir chevelu","ok":false,"why":"La transmission est surtout directe, par contact des têtes chez l'enfant en milieu scolaire, ou plus rarement indirecte (bonnets, peignes, brosses)."},{"t":"Pédiculose corporelle","ok":false,"why":"La transmission est interhumaine directe ou due aux vêtements."},{"t":"Phtiriase","ok":true,"why":"La phtiriase (poux de pubis) est une IST ; on dépiste une autre IST et on traite les partenaires."},{"t":"Impétigo de la nuque","ok":false,"why":"Il doit faire rechercher une pédiculose du cuir chevelu ; ce n'est pas une IST."},{"t":"Nodules post-scabieux","ok":false,"why":"Ce sont des lésions immuno-allergiques sans sarcopte, qui n'ont rien d'une IST."}],"explanation":"La phtiriase est une infection sexuellement transmissible : elle impose de dépister une autre IST et de traiter les partenaires.","src":"p. 257-258"},{"id":"d171-qcm-101","type":"QRM","rank":"A","objective":"d171-obj-04","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un homme de 30 ans consulte pour un prurit diffus aggravé la nuit depuis 3 semaines. Sa conjointe a les mêmes symptômes. Il présente des lésions de grattage de l'ombilic et des fesses, des vésicules perlées interdigitales et des nodules prurigineux de la verge. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une gale","ok":true,"why":"Le prurit nocturne, familial ou conjugal, avec des lésions de topographie évocatrice et des lésions spécifiques, évoque une gale."},{"t":"Le caractère conjugal du prurit est évocateur","ok":true,"why":"Un prurit conjugal ou familial doit faire penser à la gale."},{"t":"Le diagnostic est avant tout clinique","ok":true,"why":"Il repose sur l'anamnèse et la topographie des lésions."},{"t":"Le visage est habituellement atteint chez l'adulte","ok":false,"why":"Le prurit de la gale épargne le visage."},{"t":"Un examen parasitologique est obligatoire pour poser le diagnostic","ok":false,"why":"Il peut confirmer le diagnostic mais n'est jamais obligatoire."}],"explanation":"La gale typique associe un prurit diffus à recrudescence nocturne épargnant le visage, souvent familial ou conjugal, et des lésions de topographie évocatrice ; le diagnostic est clinique.","src":"p. 250, 252"},{"id":"d171-qcm-102","type":"QRM","rank":"A","objective":"d171-obj-06","tags":["clinique"],"difficulty":2,"stem":"À propos des lésions spécifiques de la gale, quelles propositions sont exactes ?","options":[{"t":"Le sillon scabieux correspond au trajet de l'acarien femelle dans la couche cornée","ok":true,"why":"C'est la définition du sillon, de quelques millimètres de long."},{"t":"Chaque sillon contient les œufs pondus","ok":true,"why":"Il contient les œufs ; à une extrémité, une discrète surélévation correspond à la position de la femelle."},{"t":"Les vésicules perlées siègent surtout dans les espaces interdigitaux","ok":true,"why":"Ce sont de petites élevures translucides sur base érythémateuse."},{"t":"Les nodules scabieux siègent surtout sur le dos","ok":false,"why":"Ils siègent surtout sur les régions génitales de l'homme."},{"t":"La surélévation à l'extrémité d'un sillon est une vésicule perlée","ok":false,"why":"Elle correspond à l'éminence acarienne, c'est-à-dire à la position de l'acarien femelle."}],"explanation":"Les lésions spécifiques de la gale sont les sillons (avec éminence acarienne), les vésicules perlées interdigitales et les nodules scabieux des régions génitales de l'homme.","src":"p. 250"},{"id":"d171-qcm-103","type":"QRM","rank":"A","objective":"d171-obj-04","tags":["clinique"],"difficulty":1,"stem":"Quelles localisations des lésions sont évocatrices de la gale chez l'adulte ?","options":[{"t":"Les espaces interdigitaux","ok":true,"why":"Topographie classique."},{"t":"La face antérieure des poignets","ok":true,"why":"Topographie classique, avec les sillons."},{"t":"L'ombilic et les fesses","ok":true,"why":"Ces zones font partie de la topographie évocatrice."},{"t":"Le mamelon et l'aréole mammaire chez la femme","ok":true,"why":"Localisation évocatrice chez la femme."},{"t":"Le visage de l'adulte, atteint précocement","ok":false,"why":"Le prurit de la gale épargne le visage chez l'adulte."}],"explanation":"Topographie évocatrice : espaces interdigitaux, face antérieure des poignets, coudes et emmanchures antérieures, ombilic, fesses, face interne des cuisses, organes génitaux externes de l'homme, mamelon et aréole de la femme ; le visage est épargné.","src":"p. 250"},{"id":"d171-qcm-104","type":"QRM","rank":"B","objective":"d171-obj-05","tags":["clinique"],"difficulty":2,"stem":"À propos de la gale hyperkératosique, quelles propositions sont exactes ?","options":[{"t":"Elle survient chez des immunodéprimés ou des sujets âgés sous immunosuppresseurs","ok":true,"why":"Le terrain typique est l'immunodépression ou la corticothérapie chez le sujet âgé en collectivité."},{"t":"Sa contagiosité est majeure en raison d'une prolifération parasitaire intense","ok":true,"why":"Elle est très contagieuse."},{"t":"Le prurit est le plus souvent discret, voire absent","ok":true,"why":"Le prurit est discret ou absent."},{"t":"Elle épargne le visage, le cuir chevelu et les ongles","ok":false,"why":"Elle peut atteindre tout le corps, y compris le visage, le cuir chevelu et les ongles."},{"t":"L'acarien y est très difficile à mettre en évidence","ok":false,"why":"La mise en évidence de l'acarien est facile dans les formes profuses et hyperkératosiques."}],"explanation":"La gale hyperkératosique touche les sujets immunodéprimés ou âgés sous immunosuppresseurs, avec une contagiosité majeure, un prurit discret et une atteinte de tout le corps.","src":"p. 252"},{"id":"d171-qcm-105","type":"QRM","rank":"B","objective":"d171-obj-05","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"À propos des formes particulières de gale, quelles propositions sont exactes ?","options":[{"t":"Chez le nourrisson, on peut observer des vésiculo-pustules palmaires et plantaires","ok":true,"why":"C'est une particularité de la gale du nourrisson."},{"t":"Chez le nourrisson, l'atteinte du visage est possible","ok":true,"why":"Une atteinte du visage chez un nourrisson doit évoquer une gale."},{"t":"La gale profuse résulte souvent d'un diagnostic tardif ou de traitements inadaptés","ok":true,"why":"Une corticothérapie locale ou générale ou un déficit immunitaire peuvent la favoriser."},{"t":"Chez le nourrisson, les paumes et les plantes sont toujours épargnées","ok":false,"why":"Les vésiculo-pustules palmaires et plantaires sont au contraire caractéristiques."},{"t":"La gale profuse survient surtout chez l'adulte jeune en bonne santé","ok":false,"why":"Elle survient souvent chez des personnes âgées, alitées, avec des troubles des fonctions supérieures."}],"explanation":"Gale du nourrisson : vésiculo-pustules palmaires et plantaires, nodules péri-axillaires, visage possible. Gale profuse : éruption étendue, diagnostic tardif, terrain immunodéprimé ou corticothérapie.","src":"p. 251, 258"},{"id":"d171-qcm-106","type":"QRM","rank":"B","objective":"d171-obj-05","tags":["complications"],"difficulty":2,"stem":"À propos des complications de la gale, quelles propositions sont exactes ?","options":[{"t":"Tout impétigo de l'adulte doit faire rechercher une gale","ok":true,"why":"Il s'agit souvent d'une impétiginisation des lésions."},{"t":"Une eczématisation peut être secondaire à la gale ou à son traitement","ok":true,"why":"C'est une complication possible."},{"t":"Les nodules post-scabieux ne contiennent pas de sarcopte et sont d'origine immuno-allergique","ok":true,"why":"Ils peuvent persister plusieurs semaines après un traitement efficace."},{"t":"Les nodules post-scabieux disparaissent toujours en 24 heures après un traitement efficace","ok":false,"why":"Ils peuvent persister plusieurs semaines."},{"t":"Les nodules post-scabieux justifient systématiquement un retraitement","ok":false,"why":"Ils ne constituent pas une indication de retraitement."}],"explanation":"Complications de la gale : impétiginisation, eczématisation, nodules post-scabieux (immuno-allergiques, sans sarcopte, sans indication de retraitement).","src":"p. 252, 254"},{"id":"d171-qcm-107","type":"QRM","rank":"B","objective":"d171-obj-09","tags":["paraclinique"],"difficulty":2,"stem":"À propos du diagnostic parasitologique et de la dermatoscopie dans la gale, quelles propositions sont exactes ?","options":[{"t":"L'examen parasitologique consiste à gratter un sillon au vaccinostyle et à examiner le prélèvement au microscope","ok":true,"why":"On recueille le matériel du sillon, si possible l'éminence acarienne, pour voir les œufs ou la femelle adulte."},{"t":"La mise en évidence de l'acarien est difficile en dehors des formes profuses et hyperkératosiques","ok":true,"why":"Ces formes contiennent beaucoup de parasites."},{"t":"La dermatoscopie montre un aspect en deltaplane et peut remplacer l'examen parasitologique","ok":true,"why":"Cet examen est plus facilement accessible en ville."},{"t":"L'examen parasitologique est obligatoire pour affirmer la gale","ok":false,"why":"Il n'est dans tous les cas pas obligatoire pour le diagnostic."},{"t":"Un signe biologique sanguin spécifique confirme la gale","ok":false,"why":"Il n'y a pas de signe biologique spécifique de gale."}],"explanation":"Le diagnostic de gale est clinique ; l'examen parasitologique (grattage d'un sillon) ou la dermatoscopie (signe du deltaplane) peuvent le confirmer, sans être obligatoires.","src":"p. 252-253"},{"id":"d171-qcm-108","type":"QRM","rank":"A","objective":"d171-obj-11","tags":["traitement","prévention"],"difficulty":2,"stem":"Un adulte a une gale commune, prise en charge à domicile. Quelles propositions thérapeutiques sont exactes ?","options":[{"t":"On traite simultanément le malade et les personnes ayant eu un contact intime avec lui","ok":true,"why":"Famille et partenaires sexuels doivent être traités en même temps."},{"t":"L'ivermectine est donnée à la dose de 200 µg/kg par voie orale puis répétée 7 à 14 jours plus tard","ok":true,"why":"La seconde prise est hors AMM mais indispensable."},{"t":"Un traitement local correctement réalisé peut suffire","ok":true,"why":"Dans la gale commune à domicile, le traitement local ou le traitement oral sont possibles."},{"t":"Une désinfection systématique de l'environnement est nécessaire","ok":false,"why":"Il n'y a pas de désinfection de l'environnement en cas de gale commune ; on lave le linge."},{"t":"Une seule prise d'ivermectine suffit","ok":false,"why":"Elle doit être répétée à 7-14 jours, du fait du cycle du parasite."}],"explanation":"Gale commune : traitement simultané du malade et des contacts intimes, local ou oral (ivermectine à répéter à 7-14 jours), lavage du linge, sans désinfection de l'environnement.","src":"p. 253-254"},{"id":"d171-qcm-109","type":"QRM","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"stem":"À propos des modalités du traitement local de la gale, quelles propositions sont exactes ?","options":[{"t":"L'application se fait sur la totalité du corps après une douche tiède au savon","ok":true,"why":"Y compris les zones génitales, le cuir chevelu et le visage en cas de doute sur leur atteinte."},{"t":"On ne se lave pas pendant 24 heures, puis on prend une douche à l'eau et au savon avec un soin émollient","ok":true,"why":"La peau est alors sèche et prurigineuse."},{"t":"L'application est renouvelée 8 jours plus tard","ok":true,"why":"Le produit agit mal sur les œufs."},{"t":"Le visage et le cuir chevelu sont toujours épargnés","ok":false,"why":"Ils sont traités s'il y a un doute sur leur atteinte."},{"t":"Une seule application détruit les œufs et suffit","ok":false,"why":"Il faut répéter l'application car l'action sur les œufs est mauvaise."}],"explanation":"Traitement local de la gale : application sur tout le corps après douche tiède, 24 heures sans lavage, soin émollient, renouvellement à 8 jours (7 jours pour la perméthrine).","src":"p. 253-254"},{"id":"d171-qcm-110","type":"QRM","rank":"A","objective":"d171-obj-11","tags":["traitement","prévention"],"difficulty":2,"stem":"Une patiente âgée, alitée, présente une gale profuse. Quelles mesures sont recommandées ?","options":[{"t":"L'isoler, idéalement en hospitalisation","ok":true,"why":"Isolement du malade."},{"t":"Associer un traitement par voie orale au traitement local","ok":true,"why":"Dans les gales profuses et hyperkératosiques, les deux sont associés."},{"t":"Définir largement les sujets contacts","ok":true,"why":"La définition des contacts est large."},{"t":"Prescrire une antibiothérapie en cas d'impétiginisation","ok":true,"why":"Une surinfection impose un traitement antibiotique."},{"t":"Se limiter à un traitement local seul","ok":false,"why":"Le traitement oral est associé dans les formes profuses et hyperkératosiques."}],"explanation":"Gale profuse ou hyperkératosique : isolement, traitement oral et local associés, sujets contacts définis largement, antibiothérapie si impétiginisation ; éviction jusqu'à négativation de l'examen parasitologique chez l'enfant.","src":"p. 254"},{"id":"d171-qcm-111","type":"QRM","rank":"B","objective":"d171-obj-13","tags":["suivi","pièges"],"difficulty":2,"stem":"Un prurit persiste 10 jours après le traitement d'une gale. Quelles causes peut-on évoquer ?","options":[{"t":"Une irritation par le traitement","ok":true,"why":"Elle est possible."},{"t":"Un eczéma de contact","ok":true,"why":"Il est possible."},{"t":"Une parasitophobie","ok":true,"why":"Cause psychologique à évoquer."},{"t":"Un échec du traitement de la gale","ok":true,"why":"Il est établi devant des lésions évocatrices et/ou un examen parasitologique positif."},{"t":"Des nodules post-scabieux contenant des sarcoptes vivants","ok":false,"why":"Les nodules post-scabieux ne contiennent pas de sarcopte."}],"explanation":"Devant un prurit persistant 8 à 15 jours après le traitement : irritation, eczéma de contact, parasitophobie, autres causes de prurit ou échec du traitement.","src":"p. 255"},{"id":"d171-qcm-112","type":"QRM","rank":"A","objective":"d171-obj-04","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Un enfant de 7 ans présente un prurit du cuir chevelu à prédominance rétro-auriculaire, avec des lésions de grattage de la nuque et des croûtes surinfectées. Quelles propositions sont exactes ?","options":[{"t":"Une pédiculose du cuir chevelu est probable","ok":true,"why":"Prurit rétro-auriculaire et lésions de grattage de la nuque sont évocateurs."},{"t":"L'agent en cause est Pediculus humanus var. capitis","ok":true,"why":"C'est le pou de tête."},{"t":"Le diagnostic de certitude repose sur la découverte de poux vivants","ok":true,"why":"Les poux sont visibles à l'œil nu et très mobiles."},{"t":"La présence de lentes vivantes suffit à affirmer le diagnostic de certitude","ok":false,"why":"Les lentes vivantes orientent seulement le diagnostic."},{"t":"Un impétigo de la nuque exclut le diagnostic de pédiculose","ok":false,"why":"Il doit au contraire faire rechercher une pédiculose."}],"explanation":"Pédiculose du cuir chevelu : enfant d'âge scolaire, prurit rétro-auriculaire, impétigo de la nuque possible ; diagnostic de certitude par la découverte de poux vivants.","src":"p. 255"},{"id":"d171-qcm-113","type":"QRM","rank":"A","objective":"d171-obj-11","tags":["traitement"],"difficulty":2,"stem":"À propos du traitement de la pédiculose du cuir chevelu, quelles propositions sont exactes ?","options":[{"t":"On utilise un produit pédiculicide sous forme de solution ou de lotion","ok":true,"why":"Ces formes sont beaucoup plus efficaces que les shampooings et les poudres."},{"t":"Un second traitement est prescrit 7 à 10 jours plus tard","ok":true,"why":"Le mauvais effet lenticide des produits l'explique."},{"t":"On ne traite pas sans avoir retrouvé de poux vivants","ok":true,"why":"Il n'y a pas de traitement présomptif."},{"t":"Les shampooings sont la forme la plus efficace","ok":false,"why":"Ils sont beaucoup moins efficaces que les solutions, lotions ou crèmes."},{"t":"Un traitement préventif par shampooing est utile","ok":false,"why":"Le traitement préventif n'a aucun intérêt et pourrait favoriser la résistance."}],"explanation":"Pédiculose du cuir chevelu : solution ou lotion, pas de traitement présomptif ni préventif, second traitement à 7-10 jours, contrôle à J2 et J12, lavage du linge à 50 °C au moins.","src":"p. 257"},{"id":"d171-qcm-114","type":"QRM","rank":"A","objective":"d171-obj-04","tags":["clinique","prévention"],"difficulty":2,"stem":"À propos de la pédiculose corporelle, quelles propositions sont exactes ?","options":[{"t":"Elle touche avec prédilection les sujets en état de précarité","ok":true,"why":"Elle est due au pou de corps."},{"t":"Elle donne un prurit et des lésions de grattage disséminées sur le tronc et la racine des membres","ok":true,"why":"Ces lésions peuvent être hémorragiques ou surinfectées."},{"t":"Les poux se trouvent dans les vêtements, notamment les coutures","ok":true,"why":"C'est le diagnostic de certitude."},{"t":"La décontamination du linge et de la literie est le plus souvent suffisante","ok":true,"why":"C'est le traitement habituel."},{"t":"Le pou de corps vit accroché aux poils, comme le pou de pubis","ok":false,"why":"Le pou de pubis seul vit accroché aux poils ; les poux de tête et de corps sont très mobiles."}],"explanation":"Pédiculose corporelle : précarité, prurit, lésions de grattage du tronc et de la racine des membres, poux dans les coutures, traitement du linge.","src":"p. 256-258"},{"id":"d171-qcm-115","type":"QRM","rank":"A","objective":"d171-obj-08","tags":["clinique","traitement"],"difficulty":2,"stem":"À propos de la phtiriase, quelles propositions sont exactes ?","options":[{"t":"Elle est due à Phtirius inguinalis","ok":true,"why":"C'est le pou de pubis."},{"t":"Elle se manifeste par un prurit pubien avec lésions de grattage, parfois des adénopathies inguinales","ok":true,"why":"Les lésions peuvent être impétiginisées."},{"t":"C'est une infection sexuellement transmissible","ok":true,"why":"On dépiste une autre IST et on traite les partenaires."},{"t":"Le rasage est le meilleur traitement à ce niveau","ok":true,"why":"Les poux de pubis relèvent sinon du même traitement que la pédiculose du cuir chevelu."},{"t":"Le pou de pubis, très mobile, circule librement sur la peau comme le pou de tête","ok":false,"why":"Le pou de pubis vit accroché aux poils de la région génitale, près de leur émergence."}],"explanation":"Phtiriase : Phtirius inguinalis, prurit pubien, IST, rasage, dépistage d'une autre IST et traitement des partenaires.","src":"p. 256-258"},{"id":"d171-qcm-116","type":"QRM","rank":"B","objective":"d171-obj-13","tags":["pièges"],"difficulty":2,"stem":"Quelles sont des causes d'échec du traitement des pédiculoses ?","options":[{"t":"Une réinfestation à partir de l'environnement","ok":true,"why":"C'est une cause d'échec."},{"t":"Une durée ou une fréquence d'utilisation insuffisantes","ok":true,"why":"Le traitement doit être suivi correctement."},{"t":"L'acquisition d'une résistance des poux","ok":true,"why":"La résistance aux insecticides est possible."},{"t":"Le remboursement intégral des spécialités","ok":false,"why":"C'est le coût qui pose problème : aucune des spécialités n'est remboursée."},{"t":"Une quantité excessive de produit appliqué","ok":false,"why":"C'est une quantité insuffisante qui est en cause."}],"explanation":"Causes d'échec : incompréhension, coût, réinfestation, durée ou fréquence insuffisantes, quantité insuffisante, forme galénique inappropriée, résistance.","src":"p. 258"},{"id":"d171-qcm-117","type":"QRM","rank":"B","objective":"d171-obj-14","tags":["prévention"],"difficulty":3,"stem":"Plusieurs cas de gale surviennent dans une collectivité de personnes âgées. Quelles propositions sont exactes ?","options":[{"t":"La stratégie est définie en concertation avec les autorités sanitaires","ok":true,"why":"La prise en charge d'une épidémie est coordonnée avec les autorités sanitaires."},{"t":"On traite au minimum toutes les personnes en contact avec les cas","ok":true,"why":"Au maximum, on traite toutes les personnes vivant, travaillant ou visitant l'institution."},{"t":"Le traitement par voie orale est utilisé dans ce contexte","ok":true,"why":"Le traitement des personnes en contact se fait par voie orale."},{"t":"Seuls les patients symptomatiques sont traités","ok":false,"why":"Les contacts sont traités, même sans symptômes."},{"t":"Il est inutile de prévenir les familles","ok":false,"why":"Il faut prévenir les familles en présence du patient ou avec son accord."}],"explanation":"Épidémie de gale en collectivité : stratégie avec les autorités sanitaires, traitement oral d'au moins tous les contacts, information des familles ; éviction des enfants jusqu'à 3 jours après le traitement.","src":"p. 254"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d171-pareto","points":[{"id":"d171-par-01","rank":"A","cat":"clinique","text":"**Gale** (Sarcoptes scabiei hominis) : prurit diffus à recrudescence **nocturne**, **épargnant le visage**, souvent **conjugal ou familial** ; diagnostic avant tout **clinique**","src":"p. 249-250, 252"},{"id":"d171-par-02","rank":"A","cat":"clinique","text":"Lésions **spécifiques** de gale : **sillons** (entre les doigts, face antérieure des poignets), **vésicules perlées**, **nodules scabieux** (OGE de l'homme) ; mamelon/aréole chez la femme","src":"p. 250"},{"id":"d171-par-03","rank":"A","cat":"traitement","text":"Gale : **ivermectine** 200 µg/kg PO en prise unique, **à répéter à 7-14 j** (AMM > 2 ans et > 15 kg) ; local : benzoate de benzyle ou **perméthrine 5 %**, à répéter à 7-8 j (mauvaise action sur les œufs)","src":"p. 253-254"},{"id":"d171-par-04","rank":"A","cat":"traitement","text":"Traiter **simultanément** le malade et ses **contacts intimes** (famille, partenaires) ; linge lavé **> 60 °C** ; pas de désinfection de l'environnement en gale commune","src":"p. 254"},{"id":"d171-par-05","rank":"A","cat":"examen","text":"Pas de signe biologique spécifique ; **bilan d'IST** si rapports sexuels à risque ; examen parasitologique ou **dermatoscopie** (signe du **deltaplane**) possibles mais non obligatoires","src":"p. 252-253"},{"id":"d171-par-06","rank":"A","cat":"gravité","text":"Gale **profuse** ou **hyperkératosique** : isolement, ivermectine **PO + local**, contacts largement définis, antibiothérapie si impétiginisation ; éviction enfant : **3 j** après traitement (commune)","src":"p. 252, 254"},{"id":"d171-par-07","rank":"A","cat":"piège","text":"**Nodules post-scabieux** persistants (immuno-allergiques, sans sarcopte) = **pas de retraitement** ; prurit persistant à 8-15 j : eczéma, irritation, **parasitophobie**, échec","src":"p. 252, 254-255"},{"id":"d171-par-08","rank":"B","cat":"clinique","text":"Formes atypiques : **nourrisson** (vésiculo-pustules palmo-plantaires, nodules péri-axillaires, visage) ; **impétigo de l'adulte** → chercher une gale (RAA/GNPS dans les pays en développement)","src":"p. 251-252, 258"},{"id":"d171-par-09","rank":"A","cat":"clinique","text":"**Pédiculose du cuir chevelu** (P. humanus capitis) : enfant d'âge scolaire, prurit **rétro-auriculaire**, **impétigo de la nuque** ; certitude = **poux vivants** ; lentes = orientation seulement","src":"p. 255"},{"id":"d171-par-10","rank":"A","cat":"clinique","text":"**Pédiculose corporelle** (P. humanus corporis) : précarité, prurit, lésions de grattage du tronc ; poux dans les **coutures** ; traitement = **linge/literie**","src":"p. 256, 258"},{"id":"d171-par-11","rank":"A","cat":"clinique","text":"**Phtiriase** (Phtirius inguinalis) : prurit pubien, adénopathies inguinales ; c'est une **IST** → dépister les autres IST, traiter les **partenaires** ; meilleur traitement = **rasage**","src":"p. 256-258"},{"id":"d171-par-12","rank":"A","cat":"traitement","text":"Pédiculicides : **solution/lotion** (pas de shampooing ni poudre), pas de traitement présomptif ; **2e traitement à 7-10 j** (lenticide insuffisant) ; poux à J2 → **changer de classe**","src":"p. 257"},{"id":"d171-par-13","rank":"A","cat":"prévention","text":"Pédiculose : lavage vêtements/literie **≥ 50 °C** ; éviction scolaire **non systématique** ; pas de désinfection des locaux ; ivermectine hors AMM en cas d'échec","src":"p. 257-258"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
